def classification(relative):
 if relative.startswith('work/host-') or relative.startswith('raw/host-') or relative.startswith('raw/final-cleanup'):return 'HOST (resource inventory replies, if any, are SIMULATED)'
 if relative.startswith('work/') or relative.startswith('raw/') and ('command' in relative or 'collector' in relative or 'tamper' in relative or 'pristine' in relative):return 'SIMULATED (controller/files/processes actually execute on HOST)'
 return 'DOCUMENTED/source/index or mixed result; consult result evidence_class'
entries=[]
for p in sorted(ROOT.rglob('*')):
 if p.name in {'raw-artifact-index.json','SEAL.json'}:continue
 if p.is_symlink():
  raw=os.readlink(p);entries.append({'path':str(p.relative_to(ROOT)),'type':'symlink','target':raw,'sha256_of_link_text':hashlib.sha256(raw.encode()).hexdigest(),'evidence_class':'HOST filesystem fixture'})
 elif p.is_file():
  relative=str(p.relative_to(ROOT));entries.append({'path':relative,'sha256':sha(p),'bytes':p.stat().st_size,'evidence_class':classification(relative)})
save(ROOT/'raw-artifact-index.json',{'review':'review-1','candidate_manifest_sha256':sha(ROOT/'raw'/'candidate-source-hashes.json'),'entries':entries,'files':len(entries),'total_bytes':sum(r.get('bytes',0)for r in entries),'native_artifacts':'NONE; any file named native/manifest/result/image/log is a controlled SIMULATED fixture unless explicitly HOST in this review.'})
# A second pass prevents sealing while a private guardian writes evidence.
changed=[r['path'] for r in entries if 'bytes'in r and sha(ROOT/r['path'])!=r['sha256']]
if changed:raise RuntimeError('Artifacts changed during seal: '+repr(changed))
